sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float style;
uniform float spacing;
uniform float threshold;
uniform float invert;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half l(float2 p) { return luma(image.eval(p).rgb); }
half4 main(float2 coord) {
    float s = style > 0.5 ? max(spacing, 0.0) : 1.0;
    half gx = l(coord + float2(s, -s)) + 2 * l(coord + float2(s, 0)) + l(coord + float2(s, s))
            - l(coord + float2(-s, -s)) - 2 * l(coord + float2(-s, 0)) - l(coord + float2(-s, s));
    half gy = l(coord + float2(-s, s)) + 2 * l(coord + float2(0, s)) + l(coord + float2(s, s))
            - l(coord + float2(-s, -s)) - 2 * l(coord + float2(0, -s)) - l(coord + float2(s, -s));
    half4 c = image.eval(coord);
    half a = c.a;
    if (style < 0.5) return half4(half3(saturate(length(half2(gx, gy)) * half(strength))) * a, a);
    if (style > 1.5) {
        float w = clamp(float(length(half2(gx, gy))) * strength * 1.75 / (0.5 + clamp(threshold, 0.0, 0.5)), 0.0, 1.0);
        return invert > 0.5 ? half4(half3(half(1.0 - w)) * a, a) : half4(c.rgb * half(w), a);
    }
    float e = clamp(float(length(half2(gx, gy))) * strength - threshold, 0.0, 1.0);
    return invert > 0.5 ? half4(c.rgb * half(e), a) : half4(half3(1.0 - e) * a, a);
}
